# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.contacts import contact_rows


def make_student(last, first, section, mail):
    return Student("100", last, first, section, mail)


class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_and_aligned(self):
        rows = contact_rows(
            [
                make_student("Thistle", "Bram", "A", "bt@x.org"),
                make_student("Arden", "Cleo", "B", "ca@x.org"),
            ]
        )
        self.assertEqual(
            rows,
            [
                "Arden, Cleo          B        ca@x.org",
                "Thistle, Bram        A        bt@x.org",
            ],
        )

    def test_missing_email_names_student(self):
        pupils = [make_student("Arden", "Cleo", "B", None)]
        with self.assertRaises(ValueError) as caught:
            contact_rows(pupils)
        self.assertIn("Arden, Cleo", str(caught.exception))

    def test_blank_email_is_missing(self):
        pupils = [make_student("Arden", "Cleo", "B", "  ")]
        with self.assertRaises(ValueError):
            contact_rows(pupils)

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])
